(function(){
'use strict';
const Engine=window.MiyarManpower;if(!Engine)return;
const KEY='miyar-manpower-plans-v1';let linkedCost=null,costUndo=null,registryRows=[],manualPositionChoice=false;const invalidCostSources=new Set();
const workspace=window.MiyarScenarioWorkspace.create({prefix:'mp',key:KEY,schema:'miyar-manpower-plan/1.0',calculate:Engine.plan,values:formValues,fill,renderResult:results,bindResult:bindResults,resultAttribute:'results',fromInput:i=>({...i,attritionPercent:i.voluntaryAttritionRate===undefined?i.attritionRate*100:i.voluntaryAttritionRate*100,voluntaryAttritionPercent:(i.voluntaryAttritionRate??i.attritionRate)*100,involuntaryAttritionPercent:(i.involuntaryAttritionRate??0)*100,newHireAttritionPercent:(i.newHireAttritionRate??0)*100,positionRevision:i.positionRevision??'',hireLeadDays:i.hireLeadDays??0,productivityGainPercent:i.productivityGain*100,retirementsFte:i.retirementsFte??0,currentNationalFte:i.currentNationalFte??'',localizationTargetPercent:i.localizationTarget===null||i.localizationTarget===undefined?'':i.localizationTarget*100})});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function fmt(n,d=2){return Number(n).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:d});}
function readPlans(){return workspace.rows();}
function savePlan(p){return workspace.save(p);}
function purposeHint(id){const hints={
 unit:['توحيد الوحدة يمنع طلب عدد مضلل: استخدم معاملات أو ساعات عمل سنوية، وقِس قدرة الفرد بالوحدة والفترة نفسيهما.','A shared unit prevents a misleading headcount: use annual cases or workload hours, and measure individual capacity in the same unit and period.'],
 baseline:['هذه نقطة البداية لقياس نمو الطلب؛ استخدم الحجم الفعلي في الفترة نفسها التي قست فيها قدرة الفرد.','This anchors demand growth; use actual volume for the same period as individual capacity.'],
 target:['يحوّل خطة الأعمال إلى احتياج قدرة. أدخل حجم العمل المتوقع، لا عدد الموظفين الذي ترغب في طلبه.','This converts the business plan into needed capacity. Enter expected workload volume rather than the headcount you want to request.'],
 capacity:['نقسم العمل على هذه القدرة لتقدير العدد. إن كانت الوحدة ساعات، استخدم ساعات الإنجاز الصافية السنوية بعد الإجازات والتدريب والغياب.','Workload is divided by this capacity to estimate staffing. For hours, use net productive annual hours after leave, training and absence.'],
 current:['يحدد القدرة الموجودة حتى لا تطلب تعيينات تغطي عملًا يمكن للفريق الحالي إنجازه. احسب الشاغلين الفعليين فقط: دوام كامل = 1 FTE ونصف دوام = 0.5.','This identifies available capacity so you do not hire for work the current team can cover. Count actual incumbents only: full-time = 1 FTE, half-time = 0.5.'],
 vacant:['الشاغر منصب غير مشغول، فلا يزيد القدرة الحالية. يُعرض لفصل الإحلال عن التوسع؛ اتركه فارغًا إذا لم يتوافر عدد موثّق.','An unfilled position adds no current capacity. This separates vacancy filling from growth; leave it blank if no documented count exists.'],
 horizon:['يحدد متى يجب توافر القدرة ويوزع نمو الطلب والتعيينات عبر السنوات. اختر أفق خطة الأعمال.','This sets when capacity is needed and spreads demand growth and hiring across years. Use the business-plan horizon.'],
 attrition:['تقدير المغادرين يكشف احتياج الإحلال الذي لا يظهر من نمو العمل وحده. استند إلى معدل مغادرة فعلي أو سيناريو معلن.','Expected leavers reveal backfill demand that workload growth alone misses. Use observed leaving rates or an explicit scenario.'],
 involuntary:['يفصل انتهاء علاقة العمل بقرار الجهة عن الاستقالات حتى لا تختلط أسباب فجوة الإحلال. لا تضف التقاعد المعروف هنا.','This separates organization-initiated exits from resignations so backfill causes stay visible. Exclude known retirements here.'],
 'new-attrition':['الاحتفاظ بالمعيّنين الجدد يؤثر في القدرة التي تضيفها خطة التوظيف؛ افصله عن معدل مغادرة الشاغلين الحاليين.','New-hire retention affects the capacity hiring adds; keep it separate from existing-incumbent attrition.'],
 'hire-days':['فجوة اليوم لا تُسد فورًا؛ هذه المدة تؤخر مباشرة التعيينات وتكشف الحاجة إلى تغطية مؤقتة. استخدم مدة التوظيف الفعلية لدى الجهة.','Today’s gap is not filled immediately; this delay exposes temporary coverage needs. Use the organization’s observed hiring lead time.'],
 hires:['هذه تعيينات ملتزم بها أصلًا، فتُخصم قدرتها المتاحة من الفجوة؛ لا تُدخل العدد الجديد الذي سيقترحه الحساب.','These are already-committed hires, whose available capacity reduces the gap; do not enter the new headcount the calculation will propose.'],
 internal:['النقل والتطوير الداخلي قد يغنيان عن تعيين خارجي؛ أدخل فقط قدرة إضافية قابلة للتحقق، لا نقلًا ينشئ فجوة مماثلة في فريق آخر.','Internal moves may avoid external hiring; count verified additional capacity, not a transfer that creates the same gap elsewhere.'],
 productivity:['تحسين العملية قد يخفض الحاجة إلى العدد. اربط النسبة بمبادرة ممولة ومقاسة؛ لا تفترض زيادة الإنتاجية لتبرير عدد أقل.','Process improvement may reduce hiring demand. Tie this rate to a funded, measured initiative rather than assuming efficiency to justify fewer staff.'],
 cost:['يحوّل عدد التعيينات إلى ميزانية تشمل التزامات صاحب العمل، لا الراتب وحده. نسحب نتيجة التعويضات المطابقة للمنصب ونسخته ودرجته عندما تتوافر.','This turns whole hires into a budget including employer obligations, not just salary. A compensation result is reused only when its position, revision and grade match.'],
 grade:['الدرجة تربط تكلفة العدد بنطاق الأجر المقيم للمنصب. تُسحب الدرجة الموثّقة من نسخة المنصب؛ إدخالها يدويًا يبقى افتراض سيناريو.','The grade links staffing cost to the evaluated pay band. A documented position grade is reused; a manually entered grade remains a scenario assumption.']
};return hints[id]?t(...hints[id]):'';}
function input(id,label,value='',attrs='',hint=''){hint=purposeHint(id)||hint;return '<label class="mp-field">'+label+'<input id="mp-'+id+'" value="'+esc(value)+'" '+attrs+(hint?' aria-describedby="mp-'+id+'-hint"':'')+'>'+(hint?'<small id="mp-'+id+'-hint" class="mp-hint">'+hint+'</small>':'')+'</label>';}
function organizeForm(content){const main=content.querySelector('#mp-strategy')?.closest('.mp-form');if(!main)return;main.classList.add('mp-core-form');const make=(attribute,title,note)=>{const detail=document.createElement('details');detail.className='mp-scenario-controls mp-progressive';detail.setAttribute(attribute,'');const summary=document.createElement('summary');summary.textContent=title;detail.append(summary);const p=document.createElement('p');p.textContent=note;detail.append(p);const grid=document.createElement('div');grid.className='mp-form';detail.append(grid);return {detail,grid};};const planning=make('data-mp-planning-options',t('توقيت التوظيف والإحلال والإنتاجية — عند الحاجة','Hiring timing, backfill and productivity — when needed'),t('ابدأ بعبء العمل والقدرة الحالية. افتح هذه الافتراضات إذا أردت احتساب المغادرين أو تعيينات ملتزم بها أو تحسن العملية؛ الأرقام المعروضة سيناريوهات قابلة للمراجعة.','Start with workload and current capacity. Open these assumptions to model leavers, committed hires or process improvement; displayed values are reviewable scenarios.'));for(const id of ['attrition','involuntary','new-attrition','hire-days','retirements','hires','internal','productivity'])planning.grid.append(content.querySelector('#mp-'+id).closest('label'));main.after(planning.detail);const scope=make('data-mp-context-options',t('تفاصيل المنصب والشواغر — اختياري','Position and vacancy details — optional'),t('نستورد هذه البيانات من نسخة المنصب المختارة عندما تكون موثّقة. الشاغر لا يمثل موظفًا يعمل؛ العدد غير المعروف يبقى فارغًا.','Documented details are imported from the selected position revision. A vacancy is not working capacity; unknown counts stay blank.'));for(const id of ['role','grade','revision','department','family','vacant'])scope.grid.append(content.querySelector('#mp-'+id).closest('label'));const objective=content.querySelector('#mp-strategy')?.closest('.mp-wide');if(objective)scope.grid.append(objective);content.querySelector('.mp-context').append(scope.detail);const unitReason=content.querySelector('#mp-unit-reason')?.closest('.mp-form');if(unitReason){unitReason.classList.add('mp-review-controls');planning.detail.append(unitReason);}const strategyHint=document.createElement('small');strategyHint.className='mp-hint';strategyHint.textContent=t('يربط العدد المطلوب بنتيجة أعمال قابلة للمراجعة، بدل إنشاء وظائف لمجرد وجود ميزانية.','This links requested staffing to a reviewable business outcome, rather than creating roles because budget is available.');content.querySelector('#mp-strategy').after(strategyHint);}
function signed(n,d=2){return (n>0?'+':n<0?'−':'')+fmt(Math.abs(n),d);}
function currentInstitution(){return window.MiyarInstitutionProfile?.read?.()||null;}
function contextControls(){return '<section class="mp-context"><h3>'+t('خطوة 1 · اختر المنصب ونسخته','Step 1 · select the position and revision')+'</h3><div class="mp-form"><label class="mp-field">'+t('المنصب من السجل','Registry position')+'<select id="mp-position"><option value="">'+t('سيناريو غير مرتبط بمنصب','Scenario without a linked position')+'</option></select></label>'+input('revision',t('نسخة المنصب','Position revision'),'','type="number" min="1" step="1" readonly')+input('grade',t('الدرجة المقيّمة للمنصب','Evaluated position grade'))+input('vacant',t('FTE الشاغر في السجل — لا يعد عرضًا','Registry vacant FTE — excluded from supply'),'','type="number" min="0" step="0.1"')+'</div><div class="action-row"><button type="button" class="button button-outline" data-mp-import-position>'+t('استيراد بيانات المنصب والشاغلين والشواغر','Import position, occupied and vacant counts')+'</button><button type="button" class="button button-outline" data-mp-import-cost>'+t('سحب تكلفة صاحب العمل لهذا المنصب والدرجة','Use employer cost for this position and grade')+'</button></div><p data-mp-context-note role="status"></p></section>';}
function contextView(plan){const i=plan.input;return '<p class="mp-profile-note">'+esc(i.positionId?t('المنصب: ','Position: ')+i.positionId+' · v'+i.positionRevision+' · '+(i.grade||t('درجة غير محددة','Grade not selected')):t('سيناريو غير مرتبط بمنصب؛ لا ينقل درجة أو تكلفة إلى سجل منصب تلقائيًا.','Unlinked scenario; it does not transfer a grade or cost to a position record automatically.'))+'</p><p class="mp-hint">'+esc(i.costContext?t('مصدر تكلفة صاحب العمل: التعويضات، بتاريخ ','Employer-cost source: Compensation, calculated ')+(i.costContext.calculatedAt||'')+' · '+(i.costContext.bandSource||''):i.annualCostPerFte===null?t('تكلفة صاحب العمل غير متاحة؛ لا يوجد تقدير مالي للعدد.','Employer cost is unavailable; there is no headcount budget estimate.'):t('تكلفة صاحب العمل افتراض يدوي يتطلب مراجعة المالية.','Employer cost is a manual assumption requiring Finance review.'))+'</p>';}
function timingView(plan){const a=plan.scenarios.base.assumptions,f=plan.scenarios.base.final;return '<div class="mp-profile-note"><strong>'+t('خطوة 2 · راجع التوقيت والتسرب والتكلفة','Step 2 · review timing, attrition and cost')+'</strong><p>'+t('مدة التعيين: ','Hiring lead: ')+fmt(a.hireLeadDays,0)+' '+t('يوم. ','days. ')+t('التسرب الطوعي / غير الطوعي / أول سنة: ','Voluntary / involuntary / first-year attrition: ')+fmt(a.voluntaryAttritionPercent)+'% / '+fmt(a.involuntaryAttritionPercent)+'% / '+fmt(a.newHireAttritionPercent)+'%. '+t('العرض من التعيينات في السنة الأخيرة: ','Hiring supply in the final year: ')+fmt(f.effectiveHiredFte)+' FTE '+t('قدرة فعالة؛ ','effective capacity; ')+fmt(f.hiredStockAtYearEndFte)+' FTE '+t('متوقع حضورهم عند نهاية السنة.','expected present at year end.')+'</p><small>'+t('التعيينات موزعة على دفعات سنوية متساوية، تبدأ كل دفعة بعد مدة التعيين. النقل الداخلي جاهز بنسبة تقدم الأفق. التكلفة ميزانية سنة كاملة للتعيينات الكاملة وليست إنفاق السنة الأولى.','Hires are spread into equal annual cohorts; each starts after the lead days. Internal moves are ready pro rata. Cost is the full-year budget for whole hires, not first-year cash expenditure.')+'</small></div>';}
function matchingCost(c){const id=document.getElementById('mp-position')?.value||'',revision=Number(document.getElementById('mp-revision')?.value),grade=document.getElementById('mp-grade')?.value.trim().split(' · ')[0],role=document.getElementById('mp-role')?.value.trim(),scope=window.MiyarEnterprise?.session?.()?.scope;return !!(c&&c.currency==='SAR'&&Number(c.annualEmployerCostPerFte)>0&&grade&&String(c.grade||'').trim().split(' · ')[0]===grade&&(!c.scope||c.scope===(scope||'guest'))&&(id?String(c.positionId)===id&&Number(c.revision)===revision:!c.positionId&&role&&String(c.role||'').trim()===role));}
function costSourceKey(c){return JSON.stringify([c?.scope||'guest',c?.positionId||'',c?.revision??null,String(c?.grade||'').split(' · ')[0],c?.role||'',c?.calculatedAt||'',c?.annualEmployerCostPerFte]);}
function invalidateCompensationCost(){if(!linkedCost)return;invalidCostSources.add(costSourceKey(linkedCost));const field=document.getElementById('mp-cost'),owned=field&&Number(field.value)===Number(linkedCost.annualEmployerCostPerFte);if(owned)field.value='';linkedCost=null;costUndo=null;if(field)field.dispatchEvent(new Event('change',{bubbles:true}));refreshCostNote();}
function latestCost(){try{return window.MiyarCompensationWorkbench?.getCostContext?.()||JSON.parse(localStorage.getItem('miyar-compensation-cost-context-v1:'+(window.MiyarEnterprise?.session?.()?.scope||'guest'))||'null');}catch{return null;}}
function refreshCostNote(){const note=document.querySelector('[data-mp-cost-note]');if(!note)return;note.textContent=linkedCost?t('مصدر التكلفة: نتيجة التعويضات المطابقة للمنصب والنسخة والدرجة، بتاريخ ','Cost source: compensation result matching the position, revision and grade, calculated ')+(linkedCost.calculatedAt||'')+' · '+(linkedCost.bandSource||''):document.getElementById('mp-cost')?.value?t('تكلفة صاحب عمل مدخلة يدويًا؛ تحقق منها مع المالية.','Manually entered employer cost; validate it with Finance.'):t('التكلفة غير متاحة. اختر المنصب ونسخته ودرجته ثم احسب التعويضات واسحب نتيجتها هنا؛ لا يُستخدم راتب أو نطاق من منصب آخر.','Cost is unavailable. Select the position, revision and grade, calculate compensation, then use its result here; another position’s salary or band is not used.');if(costUndo&&linkedCost){const undo=document.createElement('button');undo.type='button';undo.className='button button-outline';undo.dataset.mpUndoCost='';undo.textContent=t('التراجع عن تعبئة التكلفة','Undo cost fill');undo.onclick=()=>{const previous=costUndo;if(!previous)return;document.getElementById('mp-cost').value=previous.previousValue;linkedCost=previous.previousContext;costUndo=null;document.getElementById('mp-cost').dispatchEvent(new Event('change',{bubbles:true}));refreshCostNote();};note.append(' ',undo);}}
function useCost(c=latestCost(),{preserveMessage=false,automatic=false}={}){const note=document.querySelector('[data-mp-context-note]');if(!matchingCost(c)){if(note&&!preserveMessage)note.textContent=t('لا توجد نتيجة تكلفة صاحب عمل مطابقة للمنصب والنسخة والدرجة. احسبها في التعويضات أولًا.','No employer-cost result matches the selected position, revision and grade. Calculate it in Compensation first.');return false;}const field=document.getElementById('mp-cost'),owned=linkedCost&&matchingCost(linkedCost)&&Number(field.value)===Number(linkedCost.annualEmployerCostPerFte);if(automatic&&field.value.trim()&&!owned)return false;costUndo={previousValue:field.value,previousContext:linkedCost?{...linkedCost}:null};linkedCost={...c};field.value=c.annualEmployerCostPerFte;document.getElementById('mp-cost').dispatchEvent(new Event('change',{bubbles:true}));refreshCostNote();if(note)note.textContent=(preserveMessage?note.textContent+' ':'')+t('اقتراح تكلفة من نتيجة التعويضات المطابقة؛ راجع المصدر والمبلغ أدناه.','Proposed cost from the matching compensation result; review the source and amount below.');return true;}
function positionData(p){const reviewed=window.MiyarEnterpriseGrade?.contextFor?.(p),c=reviewed||(p.content||p),id=String(p.id||p.positionId||''),revision=p.revision||c.revision||1,local=id.startsWith('LOCAL-'),linked=c.evaluatedPositionId===id&&Number(c.evaluatedPositionRevision)===Number(revision),grade=reviewed?(c.salaryGrade||''):local&&linked?(c.salaryGrade||''):'';return {id,revision,title:c.title||p.title||'',jobFamily:c.jobFamily||c.field||p.jobFamily||'',department:c.department||p.department||'',strategyObjective:c.strategyObjective||'',grade,gradeSource:grade?(local?'local-review-proposal':'approved-rewards'):null,headcount:p.headcount??c.headcount,occupied:c.occupiedFte??p.occupiedFte,vacant:c.vacantFte??p.vacantFte,state:p.state};}
function selectPosition(options={}){const row=registryRows.find(p=>positionData(p).id===document.getElementById('mp-position')?.value),note=document.querySelector('[data-mp-context-note]');if(!row){if(note)note.textContent=t('سيناريو يدوي غير مرتبط: افتح تفاصيل المنصب فقط إذا احتجت تعريف الدور والدرجة. الأعداد الفعلية غير المعروفة تبقى فارغة.','Unlinked manual scenario: open position details only when role and grade identification is needed. Unknown actual counts remain blank.');for(const id of ['role','grade'])document.getElementById('mp-'+id).readOnly=false;linkedCost=null;return;}const p=positionData(row),set=(id,value)=>{const el=document.getElementById('mp-'+id);if(el)el.value=value??'';};linkedCost=null;for(const [k,v] of Object.entries({strategy:p.strategyObjective,revision:p.revision,role:p.title,family:p.jobFamily,department:p.department,grade:p.grade}))set(k,v);const known=(v)=>v!==null&&v!==undefined&&String(v).trim()!==''&&Number.isFinite(Number(v))&&Number(v)>=0;for(const id of ['role','grade'])document.getElementById('mp-'+id).readOnly=true;set('current',known(p.occupied)?p.occupied:'');set('vacant',known(p.vacant)?p.vacant:'');set('cost','');document.getElementById('mp-current').dispatchEvent(new Event('input',{bubbles:true}));refreshCostNote();if(note)note.textContent=t('اقتراح تعبئة من سجل المنصب: ','Suggested prefill from the position registry: ')+p.title+' · '+p.id+' · v'+p.revision+' · '+(p.grade||t('درجة غير موثّقة','Grade undocumented'))+'. '+t('راجع المسمى والدرجة والعدد قبل الحساب. ','Review the title, grade and counts before calculating. ')+(known(p.occupied)?t('العدد المشغول من السجل؛ الشواغر لا تُحسب قدرة متاحة.','Occupied count comes from the record; vacancies are excluded from available capacity.'):t('العدد المشغول غير موثّق، فتركناه فارغًا؛ أدخله من بيانات المؤسسة.','Occupied count is undocumented, so it remains blank; enter it from organization data.'));if(p.gradeSource==='local-review-proposal'&&note)note.textContent+=' '+t('الدرجة من مراجعة محلية مقترحة، وليست اعتمادًا من الخادم.','Grade comes from a local review proposal, not server approval.');if(!p.grade&&note)note.textContent+=' '+t('لا يوجد تقييم معتمد لهذا الإصدار؛ لم نسحب درجة أو تكلفة من حقول الطلب غير المعتمدة.','This revision has no approved evaluation; grade and cost were not pulled from unapproved request fields.');useCost(latestCost(),{preserveMessage:true,automatic:options.automatic===true});}
async function bindContext(content){const select=content.querySelector('#mp-position'),currentId=select?.value;if(!select)return;try{const rows=await window.MiyarEnterprise?.positionRegistry?.();registryRows=Array.isArray(rows)?rows:rows?.positions||[];if(!select.isConnected)return;for(const row of registryRows){const p=positionData(row);if(!p.id)continue;const o=document.createElement('option');o.value=p.id;o.textContent=p.title+' · '+p.id+' · v'+p.revision;select.append(o);}if(currentId)select.value=currentId;else if(!manualPositionChoice&&!['role','grade','strategy','department','family','baseline','target','capacity','current','vacant','cost'].some(id=>content.querySelector('#mp-'+id)?.value.trim())){const context=window.MiyarEnterprise?.positionContext?.()||window.MiyarPositionContext,row=registryRows.find(p=>positionData(p).id===String(context?.positionId||context?.id||'')&&Number(positionData(p).revision)===Number(context?.revision));if(row){select.value=positionData(row).id;selectPosition({automatic:true});}}}catch{const note=content.querySelector('[data-mp-context-note]');if(note)note.textContent=t('تعذر تحميل سجل المناصب. أعد المحاولة أو أدخل سيناريو واضحًا غير مرتبط.','The position registry could not be loaded. Retry or use an explicit unlinked scenario.');}content.querySelector('[data-mp-import-position]').onclick=selectPosition;content.querySelector('[data-mp-import-cost]').onclick=()=>useCost();select.onchange=()=>{manualPositionChoice=!select.value;if(manualPositionChoice){linkedCost=null;costUndo=null;for(const id of ['role','grade','revision','current','vacant','cost'])content.querySelector('#mp-'+id).value='';content.querySelector('#mp-current').dispatchEvent(new Event('input',{bubbles:true}));refreshCostNote();}selectPosition();};}
function invalidScenarioField(){for(const id of ['low','high'])for(const [field,min,max] of [['demand',1,500],['productivity',-50,200],['attrition',-50,50]]){const value=Number(document.getElementById('mp-'+id+'-'+field)?.value);if(!Number.isFinite(value)||value<min||value>max)return id+'-'+field;}return null;}
function calculate(){const page=document.querySelector('.mp-page');page.querySelectorAll('[aria-invalid]').forEach(x=>{x.removeAttribute('aria-invalid');x.setAttribute('aria-describedby',(x.getAttribute('aria-describedby')||'').split(' ').filter(v=>v!=='mp-input-error').join(' '));});try{Engine.normalize(formValues());}catch(e){const labels={'Baseline workload':'baseline','Target workload':'target','Capacity per FTE':'capacity','Current FTE':'current','Horizon':'horizon','Attrition':'attrition','Voluntary attrition':'attrition','Involuntary attrition':'involuntary','New-hire attrition':'new-attrition','Hiring lead days':'hire-days','Committed hires':'hires','Internal moves / reskilling':'internal','Productivity improvement':'productivity','Annual cost per FTE':'cost','Known retirements':'retirements','Current national FTE':'national','Localization target':'localization','Position revision':'revision','Vacant FTE':'vacant','Compensation cost':'cost','Scenario demand factor':'low-demand','Scenario productivity delta':'low-productivity','Scenario attrition delta':'low-attrition','Extreme workforce estimate':'unit-reason','Enter both current national':'national'};const key=Object.keys(labels).find(k=>e.message.startsWith(k)),field=document.getElementById('mp-'+(e.message.startsWith('Scenario ')?invalidScenarioField()||labels[key]||'current':labels[key]||'current'));workspace.fail(e);if(ar()&&key&&/must/.test(e.message)){document.querySelector('[data-mp-message]').textContent=t('راجع القيمة في الحقل: ','Check the value in: ')+(field?.closest('label')?.childNodes[0]?.textContent||key);}if(field){field.setAttribute('aria-invalid','true');field.setAttribute('aria-describedby',((field.getAttribute('aria-describedby')||'')+' mp-input-error').trim());for(let parent=field.parentElement;parent&&parent!==page;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;field.focus();field.scrollIntoView({block:'center'});}return null;}const result=workspace.calculate();if(result){const panel=page.querySelector('.mp-results');panel?.scrollIntoView({block:'start'});panel?.focus();}return result;}
function formValues(){const scenarioOverrides={};for(const id of ['low','high'])scenarioOverrides[id]={demandFactor:Number(document.getElementById('mp-'+id+'-demand').value)/100,productivityDelta:Number(document.getElementById('mp-'+id+'-productivity').value)/100,attritionDelta:Number(document.getElementById('mp-'+id+'-attrition').value)/100};return {positionId:document.getElementById('mp-position')?.value||'',positionRevision:document.getElementById('mp-revision')?.value||'',grade:document.getElementById('mp-grade')?.value||'',vacantFte:document.getElementById('mp-vacant')?.value??'',costContext:linkedCost,voluntaryAttritionPercent:document.getElementById('mp-attrition').value,involuntaryAttritionPercent:document.getElementById('mp-involuntary').value,newHireAttritionPercent:document.getElementById('mp-new-attrition').value,hireLeadDays:document.getElementById('mp-hire-days').value,scenarioOverrides,unitsConfirmed:document.getElementById('mp-units')?.checked===true,unitReviewReason:document.getElementById('mp-unit-reason')?.value||'',strategyObjective:document.getElementById('mp-strategy').value,role:document.getElementById('mp-role').value,department:document.getElementById('mp-department').value,jobFamily:document.getElementById('mp-family').value,workloadUnit:document.getElementById('mp-unit').value,baselineWorkload:document.getElementById('mp-baseline').value,targetWorkload:document.getElementById('mp-target').value,capacityPerFte:document.getElementById('mp-capacity').value,currentFte:document.getElementById('mp-current').value,horizonYears:document.getElementById('mp-horizon').value,attritionPercent:document.getElementById('mp-attrition').value,committedHires:document.getElementById('mp-hires').value,internalSupply:document.getElementById('mp-internal').value,productivityGainPercent:document.getElementById('mp-productivity').value,annualCostPerFte:document.getElementById('mp-cost').value,retirementsFte:document.getElementById('mp-retirements')?.value??0,currentNationalFte:document.getElementById('mp-national')?.value??'',localizationTargetPercent:document.getElementById('mp-localization')?.value??''};}
function fill(e){if(e.costContext&&invalidCostSources.has(costSourceKey(e.costContext))){e={...e,costContext:null,annualCostPerFte:''};queueMicrotask(()=>{const field=document.getElementById('mp-cost');if(field&&!field.value)field.dispatchEvent(new Event('change',{bubbles:true}));});}const select=document.getElementById('mp-position');if(e.positionId&&select&&![...select.options].some(o=>o.value===e.positionId)){const option=document.createElement('option');option.value=e.positionId;option.textContent=(e.role||e.positionId)+' · v'+e.positionRevision;select.append(option);}for(const id of ['low','high']){const v=e.scenarioOverrides?.[id]||Engine.scenarioDefs[id];for(const [field,key] of [['demand','demandFactor'],['productivity','productivityDelta'],['attrition','attritionDelta']]){const el=document.getElementById('mp-'+id+'-'+field);if(el)el.value=Number((Number(v[key])*100).toFixed(6));}}for(const [k,v] of Object.entries({position:e.positionId??'',revision:e.positionRevision??'',grade:e.grade??'',vacant:e.vacantFte??'',involuntary:e.involuntaryAttritionPercent??0,'new-attrition':e.newHireAttritionPercent??0,'hire-days':e.hireLeadDays??90,strategy:e.strategyObjective,role:e.role,department:e.department,family:e.jobFamily,unit:e.workloadUnit,baseline:e.baselineWorkload,target:e.targetWorkload,capacity:e.capacityPerFte,current:e.currentFte,horizon:e.horizonYears,attrition:e.voluntaryAttritionPercent??e.attritionPercent,hires:e.committedHires,internal:e.internalSupply,productivity:e.productivityGainPercent,cost:e.annualCostPerFte,retirements:e.retirementsFte??0,national:e.currentNationalFte??'',localization:e.localizationTargetPercent??'', 'unit-reason':e.unitReviewReason??''})){const el=document.getElementById('mp-'+k);if(el)el.value=v??'';}const units=document.getElementById('mp-units');if(units)units.checked=e.unitsConfirmed===true;linkedCost=e.costContext||null;for(const id of ['role','grade']){const field=document.getElementById('mp-'+id);if(field)field.readOnly=!!e.positionId;}refreshCostNote();}
function scenarioCard(s){const gap=s.final.rawGapFte,cls=gap>.5?'warn':gap<-.5?'surplus':'good';return '<article class="mp-scenario '+cls+'"><span>'+esc(ar()?s.labelAr:s.labelEn)+'</span><strong>'+fmt(s.final.requiredFte,2)+' FTE</strong><small>'+t('المطلوب في نهاية الأفق','Required at horizon')+'</small><div><b>'+fmt(s.final.forecastSupplyFte)+'</b><span>'+t('العرض الفعّال المتوقع','Forecast effective supply')+'</span></div><div><b class="mp-num">'+((gap>0?'+':'')+fmt(s.final.gapFte,2))+'</b><span>'+t('فجوة FTE','FTE gap')+'</span></div></article>';}
function baseTable(plan){const rows=plan.scenarios.base.years;return '<div class="mp-table-wrap"><table><thead><tr>'+[t('السنة','Year'),t('الطلب','Demand'),t('القدرة/FTE','Capacity/FTE'),t('FTE المطلوب','Required FTE'),t('العرض الفعّال المتوقع','Forecast effective supply'),t('الفجوة','Gap'),t('عدد مقترح','Suggested headcount')].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+fmt(r.year,0)+'</td><td>'+fmt(r.demand)+'</td><td>'+fmt(r.capacityPerFte)+'</td><td>'+fmt(r.requiredFte,2)+'</td><td>'+fmt(r.forecastSupplyFte)+'</td><td><span class="mp-num">'+((r.gapFte>0?'+':'')+fmt(r.gapFte,2))+'</span></td><td>'+fmt(r.recommendedHeadcount,0)+'</td></tr>').join('')+'</tbody></table></div>';}
function bridgeView(plan){const b=plan.bridge,tol=plan.input.actionToleranceFte,step=(label,value,cls='')=>'<li class="'+cls+'"><span>'+label+'</span><b>'+value+'</b></li>';let reading;
 if(b.gapFte>tol)reading=t('من فجوة '+fmt(b.gapFte,2)+' FTE: ','Of the '+fmt(b.gapFte,2)+' FTE gap: ')+(b.replacementFte>0?t(fmt(b.replacementFte,2)+' FTE لتعويض المغادرين المتوقعين — إحلال لمناصب ممولة أصلًا؛ ',fmt(b.replacementFte,2)+' FTE replaces expected leavers — backfill of already-budgeted positions; '):'')+(b.growthFte>0?t(fmt(b.growthFte,2)+' FTE من نمو الطلب — مناصب جديدة تحتاج اعتماد ميزانية.',fmt(b.growthFte,2)+' FTE comes from demand growth — new positions that need budget approval.'):t('الطلب لا يتجاوز القدرة الحالية؛ الفجوة ناتجة عن المغادرة، فراجع ضرورة كل إحلال قبل التعويض المماثل.','Demand does not exceed current capacity; the gap comes from leavers, so review whether each exit needs a like-for-like replacement.'))+(b.pipelineFte>0?t(' التعيينات والنقل المعتمد تغطي '+fmt(b.pipelineFte,2)+' FTE.',' Committed hires and internal moves already cover '+fmt(b.pipelineFte,2)+' FTE.'):'');
 else if(b.gapFte<-tol)reading=plan.actions.map(a=>ar()?a.textAr:a.textEn).join(' ');
 else reading=t('العرض والطلب متوازنان ضمن هامش ±0.5 FTE؛ لا يُقترح عدد إضافي. راقب مؤشرات الطلب والإنتاجية.','Supply and demand balance within ±0.5 FTE; no additional headcount is proposed. Monitor demand and productivity indicators.');
 return '<div class="mp-bridge"><h3>'+t('جسر القوى العاملة — من الوضع الحالي إلى نهاية الأفق (الأساس)','Workforce bridge — from today to the horizon (base)')+'</h3><ol>'+step(t('FTE الحالي','Current FTE'),fmt(b.currentFte,2))+step(t('مغادرون متوقعون (استنزاف)','Expected leavers (attrition)'),signed(-b.attritionExitsFte),'out')+step(t('تقاعد/انتهاء عقود معروف','Known retirements / contract ends'),signed(-b.knownExitsFte),'out')+step(t('تعيينات ونقل معتمد','Committed hires & internal moves'),signed(b.pipelineFte),'in')+step(t('العرض الفعّال المتوقع','Forecast effective supply'),fmt(b.forecastSupplyFte,2),'total')+step(t('FTE المطلوب','Required FTE'),fmt(b.requiredFte,2),'total')+step(t('الفجوة','Gap'),signed(b.gapFte),'gap')+'</ol><p>'+esc(reading)+'</p></div>';}
function optionsView(plan){if(!plan.options.length){const a=plan.actions[0];return '<div class="mp-hold"><strong>'+t(a.type==='defer-hires'?'مراجعة التعيينات قبل إعادة التوزيع':a.type==='move'?'إعادة توزيع قبل التوظيف':'متابعة دون توظيف إضافي',a.type==='defer-hires'?'Review unstarted hires first':a.type==='move'?'Redeploy before hiring':'Monitor without additional hiring')+'</strong><p>'+esc(plan.actions.map(x=>ar()?x.textAr:x.textEn).join(' '))+'</p></div>';}
 const card=(o)=>{const s=o.sensitivity;let title,body;
  if(o.id==='buy'){title=t('شراء · توظيف خارجي','Buy · external hiring');body=t('حتى '+fmt(o.headcount,0)+' منصب عند ندرة المهارة داخليًا أو إلحاح التوقيت. أدرج مدة الشغل المعتادة لدى الجهة في خطة التوظيف.','Up to '+fmt(o.headcount,0)+' position(s) when the skill is scarce internally or timing is urgent. Build the organization’s usual time-to-fill into the hiring plan.');}
  else if(o.id==='build'){title=t('بناء · تطوير داخلي','Build · develop internally');body=t('طوّر أو أعد تأهيل موظفين بمهارات قريبة قبل فتح شواغر؛ مناسب عندما يتسع الأفق لمدة التطوير.','Upskill or reskill employees with adjacent skills before opening vacancies; fits when the horizon allows development time.');}
  else if(o.id==='borrow'){title=t('استعارة · موارد مرنة','Borrow · flexible resources');body=o.flexFte>0?t('فرق الفجوة بين الطلب الأقل والمرتفع ≈ '+fmt(o.flexFte,2)+' FTE. وظّف دائمًا للحد المؤكد ('+fmt(o.coreFte,2)+' FTE) وغطِّ الباقي بتعاقد أو إعارة أو إسناد.','The gap spread between lower and higher demand is ≈ '+fmt(o.flexFte,2)+' FTE. Hire permanently for the firm floor ('+fmt(o.coreFte,2)+' FTE) and cover the rest through contracts, secondment or outsourcing.'):t('تعاقد أو إعارة أو إسناد للاحتياج المؤقت أو غير المؤكد.','Contracts, secondment or outsourcing for temporary or uncertain demand.');}
  else if(o.id==='bind'){title=t('احتفاظ · خفض الاستنزاف','Bind · retain talent');body=s?t('خفض الاستنزاف '+fmt(Math.abs(s.step),1)+' نقطة مئوية يغيّر الفجوة بمقدار '+signed(s.gapDeltaFte)+' FTE.','Reducing attrition by '+fmt(Math.abs(s.step),1)+' pp changes the gap by '+signed(s.gapDeltaFte)+' FTE.'):t('الاستنزاف المدخل صفر؛ لا أثر للاحتفاظ على هذه الفجوة.','Entered attrition is zero; retention does not change this gap.');}
  else {title=t('أتمتة · تحسين العمليات','Bot · automate & improve');body=t('كل +5 نقاط مئوية في الإنتاجية تغيّر الفجوة بمقدار '+signed(s.gapDeltaFte)+' FTE — بشرط مبادرة ممولة ومقاسة.','Each +5 pp of productivity changes the gap by '+signed(s.gapDeltaFte)+' FTE — only with a funded, measured initiative.');}
  return '<article data-mp-option="'+o.id+'"><strong>'+title+'</strong><p>'+esc(body)+'</p></article>';};
 return '<div class="mp-options"><h3>'+t('خيارات سد الفجوة — Buy · Build · Borrow · Bind · Bot','Options to close the gap — Buy · Build · Borrow · Bind · Bot')+'</h3><p>'+t('بدائل للفجوة نفسها وليست أعدادًا تُجمع؛ اختر مزيجًا وراجعه مع الأعمال والمالية.','Alternatives for the same gap, not quantities to add up; choose a mix and review it with the business and Finance.')+'</p><div class="mp-option-grid">'+plan.options.map(card).join('')+'</div></div>';}
function sensitivityView(plan){const gap=plan.scenarios.base.final.rawGapFte,names={demand:[t('الطلب المستهدف','Target demand'),t('+10%','+10%')],productivity:[t('الإنتاجية','Productivity'),t('+5 نقاط مئوية','+5 pp')],attrition:[t('الاستنزاف','Attrition'),null],pipeline:[t('تعيين معتمد إضافي','One more committed hire'),'+1 FTE']};
 return '<div class="mp-sensitivity"><h3>'+t('ما الذي يحرّك الفجوة؟ — السيناريو الأساسي','What moves the gap? — base scenario')+'</h3><div class="mp-sens-wrap"><table><thead><tr><th>'+t('العامل','Lever')+'</th><th>'+t('التغيير','Change')+'</th><th>'+t('أثره على الفجوة (FTE)','Gap change (FTE)')+'</th><th>'+t('الفجوة بعد التغيير','Resulting gap')+'</th></tr></thead><tbody>'+plan.sensitivity.map(r=>{const n=names[r.driver],change=n[1]||t('−'+fmt(Math.abs(r.step),1)+' نقطة مئوية','−'+fmt(Math.abs(r.step),1)+' pp');return '<tr><td>'+n[0]+'</td><td>'+change+'</td><td><span class="mp-num">'+signed(r.gapDeltaFte)+'</span></td><td><span class="mp-num">'+signed(gap+r.gapDeltaFte)+'</span></td></tr>';}).join('')+'</tbody></table></div></div>';}
function localizationView(plan){const l=plan.localization;if(!l)return '';const status=l.minimumNationalHires>0?t('لتحقيق الهدف يلزم أن يكون '+fmt(l.minimumNationalHires,0)+' على الأقل من التعيينات أو النقل الداخلي مواطنين.','At least '+fmt(l.minimumNationalHires,0)+' of the hires or internal moves must be nationals to reach the target.')+(l.exceedsTotalGap?t(' الهدف يتجاوز فجوة العدد؛ يلزم أيضًا شغل مناصب قائمة بمواطنين عند شغورها.',' The target exceeds the headcount gap; nationals must also fill existing positions as they become vacant.'):''):t('العرض المتوقع من المواطنين يحقق الهدف وفق الافتراضات الحالية.','Projected national supply meets the target under the current assumptions.');
 return '<div class="mp-localization"><h3>'+t('التوطين — هدف الجهة عند نهاية الأفق','Localization — organization target at the horizon')+'</h3><div class="mp-assumptions"><div><b>'+(l.currentRatePercent===null?'—':fmt(l.currentRatePercent)+'%')+'</b><span>'+t('نسبة التوطين الحالية','Current localization rate')+'</span></div><div><b>'+fmt(l.targetPercent)+'%</b><span>'+t('الهدف المدخل','Entered target')+'</span></div><div><b>'+fmt(l.requiredNationalFte,2)+'</b><span>'+t('FTE مواطنين مطلوب','National FTE required')+'</span></div><div><b>'+fmt(l.projectedNationalSupplyFte,2)+'</b><span>'+t('عرض المواطنين المتوقع','Projected national supply')+'</span></div></div><p><strong>'+status+'</strong></p><small>'+t('هدف تدخله الجهة؛ ليس احتسابًا لنطاقات ولا قرارًا نظاميًا. تحقّق من المتطلب الساري قبل الاعتماد.','Organization-entered target; not a Nitaqat calculation or regulatory determination. Verify the currently applicable requirement before approval.')+'</small></div>';}
function decisionSummary(plan){const b=plan.bridge,base=plan.scenarios.base.final,tol=plan.input.actionToleranceFte,flex=plan.flexibility;let text;
 if(b.gapFte>tol)text=t('خطّط لـ '+fmt(base.gapHeadcount,0)+' منصب: نحو '+fmt(Math.max(0,b.replacementFte),2)+' FTE إحلال للمغادرين ضمن الميزانية القائمة، و'+fmt(Math.max(0,b.growthFte),2)+' FTE نمو يحتاج اعتماد ميزانية.','Plan for '+fmt(base.gapHeadcount,0)+' position(s): about '+fmt(Math.max(0,b.replacementFte),2)+' FTE backfills expected leavers within the existing budget and '+fmt(Math.max(0,b.growthFte),2)+' FTE is growth that needs budget approval.')+(flex&&flex.flexFte>0?t(' غطِّ تذبذب الطلب (≈ '+fmt(flex.flexFte,2)+' FTE) بموارد مرنة.',' Cover the demand swing (≈ '+fmt(flex.flexFte,2)+' FTE) with flexible resources.'):'');
 else if(b.gapFte<-tol)text=plan.actions.map(a=>ar()?a.textAr:a.textEn).join(' ');
 else text=t('لا حاجة لعدد إضافي؛ العرض والطلب متوازنان ضمن ±0.5 FTE.','No additional headcount needed; supply and demand balance within ±0.5 FTE.');
 return '<div class="decision-summary"><strong>'+t('ماذا يعني هذا لقرارك؟','What this means for your decision')+'</strong><p>'+esc(text)+'</p></div>';}
function results(plan){const base=plan.scenarios.base,high=plan.scenarios.high,low=plan.scenarios.low,cost=base.final.annualGapCost;return '<section class="mp-results" tabindex="-1"><div class="mp-result-head"><div><span>'+t('تقدير سيناريو','SCENARIO ESTIMATE')+'</span><h2>'+esc(plan.input.role||plan.input.jobFamily||t('خطة القوى العاملة','Workforce plan'))+'</h2><p>'+esc(plan.input.strategyObjective||t('خطة مبنية على مدخلات الطلب والقدرة.','Plan based on demand and capacity inputs.'))+'</p></div><span class="mp-horizon">'+fmt(plan.input.horizonYears,0)+' '+t('سنوات','years')+'</span></div>'+contextView(plan)+decisionSummary(plan)+'<div class="mp-scenarios">'+scenarioCard(low)+scenarioCard(base)+scenarioCard(high)+'</div><div class="mp-assumptions"><div><b>'+fmt(base.assumptions.annualDemandGrowthPercent)+'%</b><span>'+t('نمو الطلب السنوي · Base','Annual demand growth · Base')+'</span></div><div><b>'+fmt(base.assumptions.cumulativeProductivityPercent)+'%</b><span>'+t('تحسن الإنتاجية التراكمي','Cumulative productivity gain')+'</span></div><div><b>'+fmt(base.assumptions.annualAttritionPercent)+'%</b><span>'+t('الاستنزاف السنوي','Annual attrition')+'</span></div><div><b>'+(cost===null?'—':fmt(cost,0)+' SAR')+'</b><span>'+t('تكلفة التعيينات الكاملة سنويًا','Annual cost of whole hires')+'</span></div></div>'+(cost!==null&&base.final.rawGapFte>0?'<p class="mp-capacity-cost">'+t('تكلفة القدرة الجزئية سنويًا: ','Annual fractional-capacity cost: ')+fmt(base.final.annualFractionalCapacityCost,0)+' SAR. '+t('هذا مكافئ حسابي للقدرة المطلوبة؛ ميزانية التعيينات الكاملة موضحة أعلاه.','This is a capacity equivalent; the budget for whole hires is shown above.')+'</p>':'')+timingView(plan)+'<h3>'+t('المسار السنوي — السيناريو الأساسي','Annual path — base scenario')+'</h3>'+baseTable(plan)+bridgeView(plan)+optionsView(plan)+sensitivityView(plan)+localizationView(plan)+'<div class="mp-uncertainty"><strong>'+t('المجهول يبقى ظاهرًا','Uncertainty stays visible')+'</strong><p>'+esc(t('النتيجة تقدير سيناريو، وليست اعتماد عدد. يجب مراجعة الطلب، القدرة، الاستنزاف، توقيت التوظيف، الإنتاجية والميزانية مع الأعمال والمالية قبل القرار.','This is a scenario estimate, not an approved headcount. Demand, capacity, attrition, hiring timing, productivity and budget must be reviewed with the business and Finance before a decision.'))+'</p></div><div class="action-row"><button class="button button-primary" type="button" data-mp-save>'+t('حفظ الخطة','Save plan')+'</button>'+(base.final.rawGapFte>.5?'<button class="button button-outline" type="button" data-mp-od>'+t('تحويل الفجوة إلى طلب OD','Send gap to OD')+'</button>':'')+'<button class="button button-outline" type="button" data-mp-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-mp-status role="status"></p></section>';}
function download(plan){const url=URL.createObjectURL(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='miyar-manpower-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function handoff(plan){const b=plan.scenarios.base.final,gap=b.gapHeadcount;if(b.rawGapFte<=.5)return;sessionStorage.setItem('miyar-manpower-handoff',JSON.stringify({strategyObjective:plan.input.strategyObjective,role:plan.input.role,department:plan.input.department,jobFamily:plan.input.jobFamily,headcount:gap,positionId:plan.input.positionId,positionRevision:plan.input.positionRevision,grade:plan.input.grade,costContext:plan.input.costContext,constraints:'Manpower planning evidence: horizon '+plan.input.horizonYears+' years; base required '+b.rawRequiredFte+' FTE; forecast supply '+b.forecastSupplyFte+' FTE; gap '+b.rawGapFte+' FTE. Validate responsibilities and job design before approval.'}));location.hash='#enterprise/create';window.dispatchEvent(new Event('hashchange'));}
function bindResults(plan){const root=document.querySelector('.mp-results');root.querySelector('[data-mp-save]').onclick=()=>{try{const r=savePlan(plan);root.querySelector('[data-mp-status]').textContent=t('حُفظت الخطة محليًا: ','Plan saved locally: ')+r.id;}catch(e){workspace.fail(e);}};root.querySelector('[data-mp-export]').onclick=()=>download(plan);const od=root.querySelector('[data-mp-od]');if(od)od.onclick=()=>handoff(plan);}
function render(){if(location.hash!=='#enterprise/manpower')return;const content=document.getElementById('ent-content');if(!content)return;const p=currentInstitution(),profileNote=p?.version?t('يستخدم الإصدار المؤسسي v','Using institution profile v')+p.version:t('لم يُعتمد إعداد مؤسسي بعد؛ ستبقى الإدارة والعائلة نصوصًا يراجعها المستخدم.','No institution profile configured yet; department and family remain user-reviewed text.');document.getElementById('enterprise-heading').textContent=t('تخطيط القوى العاملة','Manpower planning');const bc=document.getElementById('breadcrumb-title');if(bc)bc.textContent=t('تخطيط القوى العاملة','Manpower planning');document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));document.querySelector('[data-manpower-nav]')?.classList.add('active');content.innerHTML='<section class="mp-page"><div class="mp-heading"><div><span>'+t('المرحلة 2 · تخطيط القوى العاملة','PHASE 2 · MANPOWER PLANNING')+'</span><h2>'+t('من الطلب الاستراتيجي إلى فجوة قوى عاملة قابلة للفحص','From strategic demand to an inspectable workforce gap')+'</h2><p>'+t('لا يتنبأ معيار بعدد سحري. أنت تدخل الطلب والقدرة والعرض والافتراضات؛ المحرك يعرض الحساب والسيناريوهات والمجهول.','Miyar does not invent a magic headcount. You provide demand, capacity, supply and assumptions; the engine exposes the calculation, scenarios and uncertainty.')+'</p></div><button type="button" class="button button-outline" data-mp-example>'+t('تحميل مثال HC','Load HC example')+'</button></div><div class="mp-profile-note">'+esc(profileNote)+'</div>'+contextControls()+'<div class="mp-model-notice">'+t('هذا نموذج عبء عمل للأدوار التشغيلية. الأدوار المعرفية والإشرافية تحتاج تحليل احتياج ونطاق إشراف مستقل؛ لا تعتمد العدد من عبء عمل واحد.','This single-workload model estimates operational-role capacity. Knowledge and supervisory roles need separate demand and span-of-control analysis; one workload driver does not justify their headcount.')+'</div><div class="mp-form"><div class="mp-wide"><label class="mp-field">'+t('الهدف الاستراتيجي','Strategic objective')+'<textarea id="mp-strategy" rows="3"></textarea></label></div>'+input('role',t('الدور / المنصب المرجعي','Role / reference position'))+input('department',t('الإدارة','Department'))+input('family',t('العائلة الوظيفية','Job family'))+input('unit',t('وحدة قياس عبء العمل','Workload unit'),'workload units','',t('محرك العمل: معاملات، حالات، مشاريع موزونة…','The workload driver: transactions, cases, weighted projects…'))+input('baseline',t('عبء العمل الحالي','Current workload'),'','type="number" min="0.01" step="any"')+input('target',t('عبء العمل المستهدف عند نهاية الأفق','Target workload at horizon'),'','type="number" min="0.01" step="any"')+input('capacity',t('قدرة FTE واحدة حاليًا','Current capacity per FTE'),'','type="number" min="0.01" step="any"',t('صافي الإنجاز السنوي بعد الإجازات والتدريب والغياب.','Net annual output after leave, training and absence.'))+input('current',t('FTE الحالي','Current FTE'),'','type="number" min="0" step="0.1"')+input('horizon',t('الأفق بالسنوات','Horizon years'),'3','type="number" min="1" max="10" step="1"')+input('attrition',t('التسرب الطوعي السنوي %','Annual voluntary attrition %'),'5','type="number" min="0" max="100" step="0.1"')+input('involuntary',t('التسرب غير الطوعي السنوي %','Annual involuntary attrition %'),'0','type="number" min="0" max="100" step="0.1"')+input('new-attrition',t('تسرب المعيّنين الجدد في السنة الأولى %','First-year new-hire attrition %'),'10','type="number" min="0" max="100" step="0.1"')+input('hire-days',t('مدة التعيين بالأيام','Hiring lead days'),'90','type="number" min="0" max="3650" step="1"',t('تؤخر مباشرة كل دفعة سنوية وتخفض قدرتها الفعلية في سنة المباشرة.','Delays each annual hiring cohort and reduces effective capacity in its starting year.'))+input('retirements',t('تقاعد/انتهاء عقود معروف خلال الأفق (FTE)','Known retirements / contract ends over the horizon (FTE)'),'0','type="number" min="0" step="0.1"')+input('hires',t('توظيفات معتمدة خلال الأفق','Committed hires over horizon'),'0','type="number" min="0" step="0.1"')+input('internal',t('نقل/تطوير داخلي سيضيف FTE','Internal moves/upskilling adding FTE'),'0','type="number" min="0" step="0.1"')+input('productivity',t('تحسن إنتاجية تراكمي %','Cumulative productivity gain %'),'10','type="number" min="-50" max="200" step="0.1"')+input('cost',t('تكلفة صاحب العمل السنوية لكل FTE — SAR','Annual employer cost per FTE — SAR'),'','type="number" min="0.01" step="any"')+'<p class="mp-wide mp-hint" data-mp-cost-note></p></div><details class="mp-scenario-controls"><summary>'+t('افتراضات السيناريوهات — تعديل مستقل','Scenario assumptions — independent controls')+'</summary><p>'+t('افتراضيًا يتغير الطلب فقط. الإنتاجية والاستنزاف نقاط مئوية مضافة للأساس. هامش المتابعة ±0.5 FTE؛ داخله لا يُقترح عدد إضافي.','Only demand varies by default. Productivity and attrition are percentage-point changes to the base. Monitoring tolerance is ±0.5 FTE; no additional headcount is proposed inside it.')+'</p><div class="mp-form">'+['low','high'].map(id=>input(id+'-demand',t(id==='low'?'الطلب الأقل % من الأساس':'الطلب الأعلى % من الأساس',id==='low'?'Low demand % of base':'High demand % of base'),id==='low'?90:110,'type="number" min="1" max="500" step="any"')+input(id+'-productivity',t('تغير الإنتاجية — ','Productivity change — ')+id,0,'type="number" min="-50" max="200" step="any"')+input(id+'-attrition',t('تغير الاستنزاف — ','Attrition change — ')+id,0,'type="number" min="-50" max="50" step="any"')).join('')+'</div></details><details class="mp-scenario-controls mp-localization-controls"><summary>'+t('التوطين — اختياري','Localization — optional')+'</summary><p>'+t('أدخل عدد المواطنين الحالي وهدف الجهة لمعرفة الحد الأدنى من تعيينات المواطنين. لا يحسب معيار نطاقات ولا يفترض نسبة نظامية.','Enter current national FTE and the organization target to see the minimum national hiring. Miyar does not calculate Nitaqat bands or assume a regulatory percentage.')+'</p><div class="mp-form">'+input('national',t('FTE المواطنين الحاليين','Current national FTE'),'','type="number" min="0" step="0.1"')+input('localization',t('هدف التوطين للجهة %','Organization localization target %'),'','type="number" min="0" max="100" step="0.1"')+'</div></details><div class="mp-form"><p class="mp-hint">'+t('الاستنزاف 0–100% هو احتمال مغادرة الشاغل خلال سنة؛ ليس معدل دوران قد يتجاوز 100% بسبب تكرار الإحلال. يتراكب التسرب الطوعي وغير الطوعي. يبدأ حساب المعيّنين الجدد بعد مدة التعيين ويستخدم معدل السنة الأولى.','Attrition 0–100% is an incumbent’s annual leaving probability, not turnover that may exceed 100% through repeated replacement. Voluntary and involuntary probabilities compound. New hires start after the lead days and use the first-year rate.')+'</p><label><input id="mp-units" type="checkbox">'+t('راجعت وحدات عبء العمل والقدرة والفترة','I verified workload/capacity units and period')+'</label>'+input('unit-reason',t('مبرر قبول تقدير كبير — عند ظهور تنبيه','Reason for accepting a large estimate — if flagged'))+'</div><div class="mp-run"><button type="button" class="button button-primary" data-mp-run>'+t('احسب الفجوة والسيناريوهات','Calculate gap & scenarios')+'</button><span id="mp-input-error" data-mp-message role="status" aria-live="polite">'+t('كل الأرقام افتراضات قابلة للتعديل حتى يتم اعتماد بيانات المؤسسة.','All figures remain editable assumptions until organization data is approved.')+'</span></div><div data-mp-results></div></section>';content.querySelector('[data-mp-example]').onclick=()=>workspace.example(Engine.example);content.querySelector('[data-mp-run]').onclick=calculate;organizeForm(content);workspace.mount(content);content.querySelector('.mp-page').append(content.querySelector('[data-mp-saved]'));const sourceNote=content.querySelector('[data-mp-context-note]');if(sourceNote&&!sourceNote.textContent)sourceNote.textContent=t('اختر منصبًا موثّقًا لتعبئة بياناته تلقائيًا، أو أدخل أحجام العمل والقدرة يدويًا. لا نفترض عدد شاغلين أو تكلفة من دون مصدر.','Select a documented position to prefill its data, or enter workload and capacity manually. Occupied counts and cost are not assumed without a source.');bindContext(content);refreshCostNote();}

function ensureNav(){const nav=document.querySelector('.sidebar nav.nav-list');if(!nav)return;let link=nav.querySelector('[data-manpower-nav]');if(!link){link=document.createElement('a');link.href='#enterprise/manpower';link.className='nav-link';link.dataset.manpowerNav='true';link.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h16M7 16v-5m5 5V5m5 11V8"/></svg><span>'+t('تخطيط القوى العاملة','Manpower planning')+'</span>';const create=nav.querySelector('[data-enterprise-open="create"]');create?.after(link);}else link.querySelector('span').textContent=t('تخطيط القوى العاملة','Manpower planning');}
// A language switch replaces the shell without a route or enterprise event.
new MutationObserver(ensureNav).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
function consumeHandoff(){if(location.hash!=='#enterprise/create')return;let value;try{value=JSON.parse(sessionStorage.getItem('miyar-manpower-handoff')||'null');}catch{}if(!value)return;const panel=document.getElementById('miyar-od-workbench');if(!panel)return;sessionStorage.removeItem('miyar-manpower-handoff');const set=(sel,v)=>{const e=document.getElementById('ent-content')?.querySelector(sel)||document.querySelector(sel);if(e){e.value=v||'';e.dispatchEvent(new Event('input',{bubbles:true}));}};set('[data-od-strategy]',value.strategyObjective);set('[data-od-department]',value.department);set('[data-od-constraints]',value.constraints);const h=document.querySelector('[data-number="headcount"]');if(h){h.value=value.headcount;h.dispatchEvent(new Event('input',{bubbles:true}));}const status=panel.querySelector('[data-od-status]');if(status)status.textContent=t('تم استيراد فجوة القوى العاملة. أضف المسؤوليات الفعلية ثم ولّد/راجع حزمة OD.','Workforce gap imported. Add actual responsibilities, then generate/review the OD package.');panel.scrollIntoView({block:'start'});}
window.addEventListener('hashchange',()=>setTimeout(()=>{ensureNav();render();consumeHandoff();},0));window.addEventListener('miyar:navigate',()=>setTimeout(()=>{ensureNav();render();consumeHandoff();},0));document.addEventListener('click',e=>{const link=e.target.closest('[data-manpower-nav]');if(link){e.preventDefault();location.hash='#enterprise/manpower';setTimeout(render,0);}});setTimeout(()=>{ensureNav();render();consumeHandoff();},0);
window.addEventListener('miyar:compensation-cost-context',e=>{if(e.detail===null){invalidateCompensationCost();return;}if(location.hash==='#enterprise/manpower'&&matchingCost(e.detail))useCost(e.detail,{automatic:true});});
document.addEventListener('input',e=>{if(['mp-cost','mp-position','mp-revision','mp-grade','mp-role'].includes(e.target.id)){if(linkedCost&&e.target.id!=='mp-cost'){const cost=document.getElementById('mp-cost');if(cost)cost.value='';}linkedCost=null;costUndo=null;refreshCostNote();}},true);
window.addEventListener('miyar:session',()=>{linkedCost=null;costUndo=null;registryRows=[];manualPositionChoice=false;invalidCostSources.clear();});
window.MiyarManpowerWorkbench={render,readPlans,KEY,getResult:workspace.result,useCost,selectPosition};
})();
